def sem(rs1, rs2, state):
    # custom-0, funct3=0x5 : RQCFG   state['rq_m'] = rs1   (he so nhan M, int32)
    # custom-0, funct3=0x4 : REQUANT rd = sat8( (sext32(rs1) * M + (1 << (S-1))) >> S )
    #                        rs1 = tong tich luy, rs2[5:0] = S (so bit dich, 1..31)
    f3 = state.get('imm_funct3', 0x4)
    if f3 == 0x5:
        state['rq_m'] = rs1 & 0xFFFFFFFF
        return rs1 & 0xFFFFFFFF, state
    unsigned_out = state.get('imm_acc', 0) & 1
    a = rs1 & 0xFFFFFFFF
    if a & 0x80000000:
        a -= 0x100000000                      # sext32 -> so nguyen Python
    m = state.get('rq_m', 1) & 0xFFFFFFFF
    if m & 0x80000000:
        m -= 0x100000000
    s = rs2 & 0x3F
    if s == 0:
        y = a * m
    else:
        y = (a * m + (1 << (s - 1))) >> s     # dich phai lam tron nua-len, chia san am
    lo, hi = (0, 255) if unsigned_out else (-128, 127)
    if y < lo:
        y = lo
    elif y > hi:
        y = hi
    return y & 0xFFFFFFFF, state
